const crypto = require('crypto');

return [{
  case_id: crypto.randomUUID(),
  retrieved_at: new Date().toISOString(),
  case_spec: $json.case_spec,
  facts: [],
  sources: []
}];

// Get the two items returned by "Get Countries"
const items = $items("Get Countries");

// items[0].json = metadata
// items[1].json = array of country + aggregate records
const records = items?.[1]?.json;

if (!Array.isArray(records)) {
  throw new Error(
    `Expected item 1 of "Get Countries" to be an array. Got: ${typeof records}`
  );
}

// Filter out aggregates (World Bank aggregates have region.id === 'NA')
const realCountries = records.filter(r => r?.region?.id && r.region.id !== 'NA');

// Return one n8n item per country (keep the full record intact)

// -----------------------------------------------------------------------------
// SUPPLEMENTAL COUNTRIES (added 2026-06-23 — Patrick Diamitani)
// World Bank omits certain territories Atlas supports. Without this list they
// never reach blob storage. Add new entries here as needed (one per country).
// Roll back: restore versionId ad00198a-ff18-4463-93ff-ee6cabca8941
// -----------------------------------------------------------------------------
const wbMissingCountries = [
  {
    id: 'TWN', iso2Code: 'TW', name: 'Taiwan',
    region: { id: 'EAS', value: 'East Asia & Pacific' },
    adminregion: { id: '', value: '' },
    incomeLevel: { id: 'HIC', value: 'High income' },
    lendingType: { id: 'LNX', value: 'Not classified' },
    capitalCity: 'Taipei', longitude: '121.5654', latitude: '25.0330'
  },
  {
    id: 'XKX', iso2Code: 'XK', name: 'Kosovo',
    region: { id: 'ECS', value: 'Europe & Central Asia' },
    adminregion: { id: 'ECA', value: 'Europe & Central Asia (excl. high income)' },
    incomeLevel: { id: 'UMC', value: 'Upper middle income' },
    lendingType: { id: 'IBD', value: 'IBRD' },
    capitalCity: 'Pristina', longitude: '21.1655', latitude: '42.6629'
  },
  {
    id: 'MAC', iso2Code: 'MO', name: 'Macau',
    region: { id: 'EAS', value: 'East Asia & Pacific' },
    adminregion: { id: '', value: '' },
    incomeLevel: { id: 'HIC', value: 'High income' },
    lendingType: { id: 'LNX', value: 'Not classified' },
    capitalCity: 'Macau', longitude: '113.5439', latitude: '22.1987'
  }
];
const existingIso3 = new Set(realCountries.map(r => r.id));
const supplemental = wbMissingCountries.filter(c => !existingIso3.has(c.id));
const allCountries = [...realCountries, ...supplemental];

return allCountries.map(r => ({ json: r }));

const items = $input.all().map(i => i.json);

function looksLikeMeta(x) {
  return x && typeof x === 'object' && x.page !== undefined && x.pages !== undefined;
}

const output = [];

for (let i = 0; i < items.length; i += 2) {
  const meta = items[i];
  const rows = items[i + 1];

  // Validate pair structure
  if (!looksLikeMeta(meta) || !Array.isArray(rows)) {
    continue;
  }

  // Rows are newest â†’ oldest; pick first non-null value
  const latest = rows.find(r => r && r.value !== null && r.value !== undefined);
  if (!latest) continue;

  const iso3 = latest.countryiso3code;
  if (!iso3) continue;

  output.push({
    json: {
      iso3,
      unemployment: latest.value
    }
  });
}

return output;

