// Extract and organize Atlas Vantage country data
const input = $input.all();
const output = [];

for (const item of input) {
  const response = item.json;

  // Skip failed requests
  if (!response || response.status !== '200' || !response.data) {
    continue;
  }

  // Get the first (and typically only) country from the data object
  const countryKey = Object.keys(response.data)[0];
  if (!countryKey) continue;

  const c = response.data[countryKey];

  output.push({
    json: {
      iso3: c.iso3,
      atlas_iso2: c.iso2,
      atlas_name: c.name,
      atlas_name_official: c.name_off?.en,
      atlas_region: c.reg_name,
      atlas_capital: c.cap,
      atlas_capital_population: c.capi?.popu,
      atlas_lat: c.lat,
      atlas_lon: c.lon,
      atlas_income_level: c.monetary?.inc_levl,
      atlas_currency: c.monetary?.curr,
      atlas_currency_symbol: c.monetary?.curr_symbol,
      atlas_timezone: c.tzon ? Object.keys(c.tzon)[0] : null,
      atlas_languages: c.lang,
      atlas_borders: c.bord,
      atlas_continent: c.cont,
      atlas_work_hours_weekly: c.work_hours,
      atlas_website_slug: c.website_slug,
      // Indicators
      atlas_population: c.indicats?.popu_val,
      atlas_population_date: c.indicats?.popu_dat,
      atlas_urban_population_pct: c.indicats?.urbp_val,
      atlas_gdp_per_capita: c.indicats?.gdpe_val,
      atlas_gdp_growth_pct: c.indicats?.gdpg_val,
      atlas_gni_per_capita: c.indicats?.gdpc_val,
      atlas_unemployment_pct: c.indicats?.unem_val,
      atlas_labor_force_participation: c.indicats?.labf_val,
      atlas_total_labor_force: c.indicats?.laft_val,
      atlas_female_labor_force_pct: c.indicats?.laff_val,
      atlas_life_expectancy: c.indicats?.lifx_val,
      atlas_gini_index: c.indicats?.gini_val,
      atlas_inflation_pct: c.indicats?.infc_val,
      atlas_internet_coverage_pct: c.indicats?.incv_val,
      atlas_electricity_coverage_pct: c.indicats?.elcv_val,
      atlas_mobile_subscriptions_per_100: c.indicats?.mobs_val,
      atlas_bank_account_pct: c.indicats?.bacv_val,
      atlas_healthcare_coverage_pct: c.indicats?.uhcv_val,
      atlas_regulatory_quality_pct: c.indicats?.regq_val,
      atlas_rule_of_law_pct: c.indicats?.rolr_val,
      atlas_corruption_control_pct: c.indicats?.ccor_val,
      atlas_logistics_performance: c.indicats?.logp_val,
      // Atlas Scores
      atlas_total_score: c.atlas_score?.sTS,
      atlas_economic_score: c.atlas_score?.sEC,
      atlas_compliance_score: c.atlas_score?.sCM,
      atlas_workforce_score: c.atlas_score?.sWF,
      atlas_infrastructure_score: c.atlas_score?.sIF,
      // URLs
      atlas_cia_factbook_url: c.urls?.ciagov,
      atlas_video_url: c.video_vimeo_url
    }
  });
}

return output;

// Extract and organize Atlas Vantage insights data
const input = $input.all();
const output = [];

for (const item of input) {
  const response = item.json;

  // Skip failed requests
  if (!response || response.status !== '200' || !response.data) {
    continue;
  }

  const d = response.data;

  // Helper to strip HTML tags for cleaner text
  function stripHtml(html) {
    if (!html) return '';
    return html
      .replace(/<h3>/gi, '\n### ')
      .replace(/<\/h3>/gi, '\n')
      .replace(/<p>/gi, '\n')
      .replace(/<\/p>/gi, '')
      .replace(/<ul>/gi, '')
      .replace(/<\/ul>/gi, '')
      .replace(/<li>/gi, '\n- ')
      .replace(/<\/li>/gi, '')
      .replace(/<strong>/gi, '**')
      .replace(/<\/strong>/gi, '**')
      .replace(/<em>/gi, '*')
      .replace(/<\/em>/gi, '*')
      .replace(/<[^>]*>/g, '')
      .replace(/&quot;/g, '"')
      .replace(/&rsquo;/g, "'")
      .replace(/&ldquo;/g, '"')
      .replace(/&rdquo;/g, '"')
      .replace(/&mdash;/g, 'â€”')
      .replace(/&ndash;/g, 'â€“')
      .replace(/&amp;/g, '&')
      .replace(/&#39;/g, "'")
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }

  // We need to get the iso2 from the request URL since insights response doesn't include it
  // The iso2 is passed through from the previous node
  const iso2 = item.json._pairedIso2 || $('Atlas Vantage - Get Country Insights').item?.json?.iso2Code;

  output.push({
    json: {
      insights_employment_relationship: d.erelation ? stripHtml(d.erelation.content) : null,
      insights_employment_contracts: d.agreement ? stripHtml(d.agreement.content) : null,
      insights_probation_period: d.probation ? stripHtml(d.probation.content) : null,
      insights_working_hours: d.workhours ? stripHtml(d.workhours.content) : null,
      insights_minimum_age: d.empminage ? stripHtml(d.empminage.content) : null,
      insights_public_holidays: d.statholid ? stripHtml(d.statholid.content) : null,
      insights_vacation_leave: d.paidleave ? stripHtml(d.paidleave.content) : null,
      insights_sick_leave: d.sickleave ? stripHtml(d.sickleave.content) : null,
      insights_maternity_leave: d.maternity ? stripHtml(d.maternity.content) : null,
      insights_paternity_leave: d.paternity ? stripHtml(d.paternity.content) : null,
      insights_compensation: d.compensat ? stripHtml(d.compensat.content) : null,
      insights_termination: d.terminate ? stripHtml(d.terminate.content) : null,
      insights_social_security: d.socialsec ? stripHtml(d.socialsec.content) : null,
      insights_taxation: d.taxations ? stripHtml(d.taxations.content) : null,
      insights_immigration: d.immigrate ? stripHtml(d.immigrate.content) : null
    }
  });
}

return output;

// Generate both JSON and Markdown formats for each country
const input = $input.all();
const output = [];

function normalizeCountryName(name) {
  if (!name || typeof name !== 'string') return null;
  return name
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}


// World Bank name -> Onspring common-name aliases.
// Verified against live Onspring report rows (execution 31127, 2026-07-13):
// these 25 countries EXIST in Onspring under the alias, but the World Bank
// name never matched, so their Onspring sections were silently empty.
const ONSPRING_NAME_ALIASES = {
  'bahamas the': ['Bahamas'],
  'brunei darussalam': ['Brunei'],
  'cabo verde': ['Cape Verde'],
  'egypt arab rep': ['Egypt'],
  'gambia the': ['Gambia'],
  'hong kong sar china': ['Hong Kong'],
  'iran islamic rep': ['Iran'],
  'korea dem people s rep': ['North Korea'],
  'korea rep': ['South Korea'],
  'kyrgyz republic': ['Kyrgyzstan'],
  'lao pdr': ['Laos'],
  'macao sar china': ['Macau', 'Macao'],
  'puerto rico us': ['Puerto Rico'],
  'russian federation': ['Russia'],
  'samoa': ['Western Samoa'],
  'slovak republic': ['Slovakia'],
  'somalia fed rep': ['Somalia'],
  'syrian arab republic': ['Syria'],
  'timor leste': ['East Timor', 'Timor Leste'],
  'turkiye': ['Turkey', 'Turkiye'],
  'turks and caicos islands': ['Turks & Caicos'],
  'venezuela rb': ['Venezuela'],
  'viet nam': ['Vietnam'],
  'virgin islands u s': ['US Virgin Islands'],
  'yemen rep': ['Yemen'],
};

function stripHtml(html) {
  if (!html || typeof html !== 'string') return null;
  return html
    .replace(/<\s*br\s*\/?\s*>/gi, '\n')
    .replace(/<\s*\/p\s*>/gi, '\n')
    .replace(/<\s*p[^>]*>/gi, '')
    .replace(/<\s*li[^>]*>/gi, '- ')
    .replace(/<\s*\/li\s*>/gi, '\n')
    .replace(/<\s*ul[^>]*>/gi, '')
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&rsquo;/gi, "'")
    .replace(/&ldquo;/gi, '"')
    .replace(/&rdquo;/gi, '"')
    .replace(/\r\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function cleanText(value) {
  if (value === null || value === undefined) return null;
  if (typeof value !== 'string') return value;
  const cleaned = stripHtml(value);
  if (!cleaned) return null;
  return cleaned;
}

function toNumberOrNull(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string') {
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
  }
  return null;
}

function buildOnspringRows(nodeName) {
  const items = $items(nodeName);
  if (!items || !items.length) return [];
  const report = items[0].json;
  if (!report || !Array.isArray(report.columns) || !Array.isArray(report.rows)) return [];
  return report.rows.map(row => {
    const obj = { recordId: row.recordId };
    report.columns.forEach((col, idx) => {
      obj[col] = row.cells[idx];
    });
    return obj;
  });
}

function getFromMap(map, nameCandidates) {
  for (const name of nameCandidates) {
    const key = normalizeCountryName(name);
    if (key && map.has(key)) return map.get(key);
  }
  return null;
}

function formatMdValue(value) {
  if (!value) return 'N/A';
  const text = String(value);
  if (text.includes('\n')) {
    return `\n  ${text.replace(/\n/g, '\n  ')}`;
  }
  return text;
}

// Build Onspring maps once
const onspringBenefitsRows = buildOnspringRows('Onspring - Get Country Benefits');
const onspringPocRows = buildOnspringRows('Onspring - Get Point of Contact');
const onspringTasksRows = buildOnspringRows('Onspring - Get Country Tasks Data');
const onspringEntityRows = buildOnspringRows('Onspring - Get Country Entity Readiness');
const onspringKnowledgeRows = buildOnspringRows('Onspring - Get Country Knowledge');
const onspringEmployeeRows = buildOnspringRows('Onspring - Get Country Employee Count');

// ===================================================================
// OVERWRITE-SAFETY GUARD (added 2026-06-23 — Patrick Diamitani)
// The blob write OVERWRITES every country file on each run. If any
// required Onspring report returns no rows (e.g. lost API access),
// this guard stops the run BEFORE any blob write, preserving the
// last-good files. The error message names the exact failed report(s).
// To roll back this change: restore versionId ad00198a-ff18-4463-93ff-ee6cabca8941
// ===================================================================
const onspringHealth = {
  'Report 978 (Point of Contact)':  onspringPocRows.length,
  'Report 1164 (Country Tasks)':    onspringTasksRows.length,
  'Report 1035 (Benefits)':         onspringBenefitsRows.length,
  'Report 954 (Entity Readiness)':  onspringEntityRows.length,
  'Report 971 (Country Knowledge)': onspringKnowledgeRows.length,
  'Report 703 (Employee Count)':    onspringEmployeeRows.length,
};
const failedReports = Object.entries(onspringHealth).filter(([,c]) => c === 0).map(([n]) => n);
if (failedReports.length > 0) {
  throw new Error(
    'BLOB WRITE BLOCKED to protect existing country files. ' +
    'These Onspring reports returned no data: ' + failedReports.join('; ') +
    '. No files were overwritten. Restore report access and re-run. ' +
    'Health: ' + JSON.stringify(onspringHealth)
  );
}
// ===================================================================
// END GUARD
// ===================================================================



const benefitsByCountry = new Map();
for (const row of onspringBenefitsRows) {
  const country = cleanText(row['Country']);
  if (!country) continue;
  const key = normalizeCountryName(country);
  if (!key) continue;
  benefitsByCountry.set(key, {
    source: 'Onspring',
    region: cleanText(row['Region']),
    medical_supplemental: cleanText(row['Medical (Supplemental)']),
    dental_supplemental: cleanText(row['Dental (Supplemental)']),
    optical_supplemental: cleanText(row['Optical (Supplemental)']),
    life_supplemental: cleanText(row['Life (Supplemental)']),
    ltd_supplemental: cleanText(row['LTD (Supplemental)']),
    std_supplemental: cleanText(row['STD (Supplemental)']),
    travel_insurance: cleanText(row['Travel Insurance']),
    employee_assistance_program: cleanText(row['Employee Assistance Program (EAP)']),
    additional_benefits: cleanText(row['Additional benefits/comments'])
  });
}

const pocByCountry = new Map();
for (const row of onspringPocRows) {
  const country = cleanText(row['Country']);
  if (!country) continue;
  const key = normalizeCountryName(country);
  if (!key) continue;
  const list = pocByCountry.get(key) || [];
  list.push({
    source: 'Onspring',
    name: cleanText(row['Point of Contact']),
    role: cleanText(row['Role']),
    region: cleanText(row['Regions']),
    sub_region: cleanText(row['Sub-Regions'])
  });
  pocByCountry.set(key, list);
}

const tasksByCountry = new Map();
for (const row of onspringTasksRows) {
  const country = cleanText(row['Country']);
  if (!country) continue;
  const key = normalizeCountryName(country);
  if (!key) continue;
  const list = tasksByCountry.get(key) || [];
  list.push({
    source: 'Onspring',
    record_id: row['Record ID'],
    task_name: cleanText(row['Task Name']),
    region: cleanText(row['Regions']),
    task_owner: cleanText(row['Task Owner']),
    task_group: cleanText(row['Task Group']),
    response: cleanText(row['Response']),
    task_status: cleanText(row['Task Status']),
    doc_link: cleanText(row['Doc link']),
    important_links: cleanText(row['Important Links']),
    sharepoint_link: cleanText(row['SharePoint Link'])
  });
  tasksByCountry.set(key, list);
}

const entityByCountry = new Map();
for (const row of onspringEntityRows) {
  const country = cleanText(row['Country']);
  if (!country) continue;
  const key = normalizeCountryName(country);
  if (!key) continue;
  entityByCountry.set(key, {
    source: 'Onspring',
    region: cleanText(row['Region']),
    entity: cleanText(row['Entity']),
    entity_status: cleanText(row['Entity Status']),
    can_sponsor: cleanText(row['Can Atlas sponsor in this country?'])
  });
}

const employeeByCountry = new Map();
for (const row of onspringEmployeeRows) {
  const country = cleanText(row['Country']);
  if (!country) continue;
  const key = normalizeCountryName(country);
  if (!key) continue;
  employeeByCountry.set(key, {
    source: 'Onspring',
    region: cleanText(row['Region']),
    entity_status: cleanText(row['Entity Status']),
    internal_employees: toNumberOrNull(row['Number of Internal Employees']),
    wse_employees: toNumberOrNull(row['Number of WSEs']),
    total_employees: toNumberOrNull(row['Total Employees'])
  });
}

const knowledgeByCountry = new Map();
for (const row of onspringKnowledgeRows) {
  const country = cleanText(row['Country']);
  if (!country) continue;
  const key = normalizeCountryName(country);
  if (!key) continue;
  const answer = cleanText(row['In Country Partner - Answer']);
  if (!answer) continue; // keep only answered questions for clean RAG data
  const list = knowledgeByCountry.get(key) || [];
  list.push({
    source: 'Onspring',
    record_id: row['Record Id'],
    number: row['Number'],
    question_group: cleanText(row['Question Group']),
    topic: cleanText(row['Topic']),
    question: cleanText(row['Question Text']),
    answer
  });
  knowledgeByCountry.set(key, list);
}

for (const item of input) {
  const c = item.json;
  if (!c || (!c.name && !c.id && !c.iso3 && !c.iso2Code && !c.atlas_iso2)) {
    continue;
  }
  const timestamp = new Date().toISOString();
  const nameCandidates = [c.name, c.atlas_name, c.atlas_name_official].filter(Boolean);
  // Expand with Onspring aliases so World Bank naming variants still match.
  const aliasCandidates = [];
  for (const cand of nameCandidates) {
    const extra = ONSPRING_NAME_ALIASES[normalizeCountryName(cand)];
    if (extra) aliasCandidates.push(...extra);
  }
  nameCandidates.push(...aliasCandidates);

  const onspringBenefits = getFromMap(benefitsByCountry, nameCandidates);
  const onspringPocs = getFromMap(pocByCountry, nameCandidates);
  const onspringTasks = getFromMap(tasksByCountry, nameCandidates);
  const onspringEntity = getFromMap(entityByCountry, nameCandidates);
  const onspringEmployees = getFromMap(employeeByCountry, nameCandidates);
  const onspringKnowledge = getFromMap(knowledgeByCountry, nameCandidates);

  const onspringData = {};
  if (onspringPocs && onspringPocs.length) onspringData.point_of_contact = onspringPocs;
  if (onspringEntity) onspringData.entity_readiness = onspringEntity;
  if (onspringEmployees) onspringData.employee_counts = onspringEmployees;
  if (onspringBenefits) onspringData.benefits = onspringBenefits;
  if (onspringTasks && onspringTasks.length) onspringData.tasks = onspringTasks;
  if (onspringKnowledge && onspringKnowledge.length) {
    onspringData.knowledge = {
      source: 'Onspring',
      answered_count: onspringKnowledge.length,
      answered_questions: onspringKnowledge
    };
  }

  const hasOnspring = Object.keys(onspringData).length > 0;
  const sources = ['World Bank', 'Atlas Vantage'];
  if (hasOnspring) sources.push('Onspring');

  const regionPreferred = onspringEntity?.region || onspringBenefits?.region || onspringEmployees?.region || c.region?.value || c.atlas_region;
  const regionSource = onspringEntity?.region || onspringBenefits?.region || onspringEmployees?.region ? 'Onspring' : (c.region?.value ? 'World Bank' : 'Atlas Vantage');

  // Build comprehensive JSON object
  const jsonData = {
    metadata: {
      iso3: c.id || c.iso3,
      iso2: c.iso2Code || c.atlas_iso2,
      name: c.name,
      official_name: c.atlas_name_official,
      last_updated: timestamp,
      sources
    },
    geography: {
      region: regionPreferred,
      region_source: regionSource,
      capital: c.capitalCity || c.atlas_capital,
      latitude: c.latitude || c.atlas_lat,
      longitude: c.longitude || c.atlas_lon,
