  md += `## Economic Indicators\n`;
  md += `*Source: World Bank / Atlas Vantage*\n`;
  md += `- **GDP per Capita:** $${(c.gdpPerCapitaInUSD || c.atlas_gdp_per_capita || 0).toLocaleString()} USD\n`;
  md += `- **GNI per Capita:** $${(c.gniPerCapita || c.atlas_gni_per_capita || 0).toLocaleString()} USD\n`;
  md += `- **GDP Growth:** ${c.atlas_gdp_growth_pct || 'N/A'}%\n`;
  md += `- **Inflation Rate:** ${c.atlas_inflation_pct || 'N/A'}%\n`;
  md += `- **GINI Index:** ${c.atlas_gini_index || 'N/A'}\n\n`;

  md += `## Workforce & Labor Market\n`;
  md += `*Source: World Bank / Atlas Vantage*\n`;
  md += `- **Unemployment Rate:** ${c.unemployment || c.atlas_unemployment_pct || 'N/A'}%\n`;
