return output;

// Per-country Onspring coverage digest — runs every weekly execution.
// Emails a summary and flags regressions (file count drop or a country that
// previously had Onspring data coming back empty).
const items = $input.all();

// Countries with no records in ANY of the 6 Onspring reports as of 2026-07-16.
// Empty Onspring data for these is expected, not a regression.
const EXPECTED_MISSING = new Set([
  'congo rep', 'micronesia fed sts', 'sao tome and principe',
  'sint maarten dutch part', 'st kitts and nevis', 'st martin french part',
  'st vincent and the grenadines',
]);

function norm(name) {
  if (!name || typeof name !== 'string') return null;
  return name.toLowerCase().replace(/&/g, 'and').replace(/[^a-z0-9]+/g, ' ').trim();
}

const emptyCountries = [];
let populated = 0;
for (const it of items) {
  const j = it.json;
  let content = j.json_content;
  if (typeof content === 'string') {
    try { content = JSON.parse(content); } catch (e) { content = null; }
  }
  const ons = content && content.onspring;
  const has = ons && typeof ons === 'object' && Object.keys(ons).length > 0;
  if (has) populated++;
  else emptyCountries.push(j.country_name || j.iso3 || 'UNKNOWN');
}

const total = items.length;
const unexpected = emptyCountries.filter(n => !EXPECTED_MISSING.has(norm(n)));
const alert = total < 200 || unexpected.length > 0;

const status = alert ? '⚠️ ISSUES' : '✅ OK';
const subject = `[Country Data Weekly] ${status} — ${populated}/${total} countries with Onspring data`;

let html = `<h2>Country Data Weekly Run — Coverage Report</h2>`;
html += `<p><b>Country files written:</b> ${total}<br>`;
html += `<b>With Onspring data:</b> ${populated}<br>`;
html += `<b>Empty Onspring (expected, no Onspring records):</b> ${emptyCountries.length - unexpected.length}<br>`;
html += `<b>Empty Onspring (UNEXPECTED — regression):</b> ${unexpected.length}</p>`;
if (total < 200) {
  html += `<p style="color:red"><b>⚠️ File count ${total} is below the 200 floor — investigate before trusting blob data.</b></p>`;
}
if (unexpected.length) {
  html += `<p style="color:red"><b>⚠️ Countries that lost Onspring data this run:</b></p><ul>`;
  for (const n of unexpected.sort()) html += `<li>${n}</li>`;
  html += `</ul>`;
}
html += `<p style="color:#666;font-size:12px">Workflow: Country Data - Weekly Transformation and Storage · `;
html += `<a href="https://atlas-hxm.app.n8n.cloud/workflow/eceGV7Ka0Ut57rBf">open in n8n</a></p>`;

return [{ json: { subject, emailHtml: html, alert, total, populated,
  empty_count: emptyCountries.length, unexpected_empty: unexpected } }];
